WITH valid AS (SELECT *, ROUND(status_bits / temp_c, 2) AS status_bits_per_temp_c, CASE WHEN device_code = 'DV-01' THEN 1 ELSE 0 END AS is_dv_01 FROM device_readings WHERE reading_ts > DATE '2025-09-01'), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 45 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM valid), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, firmware, status_bits_per_temp_c, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps), metrics AS (SELECT id, device_code, temp_c, pressure, status_bits, status_bits_per_temp_c, MIN(session_no) OVER w_ordered AS last3_min_session_no, SUM(session_no) OVER w_ordered AS last3_sum_session_no, MAX(session_no) OVER w_ordered AS last3_max_session_no FROM sessions_device_readings WINDOW w_ordered AS (PARTITION BY device_code ORDER BY pressure ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)), kept_keys AS (SELECT id FROM metrics INTERSECT SELECT id FROM device_readings WHERE reading_ts < '2024-11-01'), reconciled AS (SELECT s.* FROM metrics s INNER JOIN kept_keys k ON s.id = k.id) SELECT id, device_code, temp_c, pressure, status_bits, last3_sum_session_no, last3_max_session_no FROM reconciled ORDER BY pressure DESC NULLS FIRST, last3_max_session_no ASC;
